const D = { scale:1, energy:.6, harmonics:4, density:.5, speed:1, hue:200, x:.5, y:.5, style:'blueprint', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width,height), cx=width*P.x, cy=height*P.y, t=K.t, sty=P.style;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const H = Math.max(2, Math.min(5, Math.round(P.harmonics)));
const N = Math.max(150, Math.min(240, Math.round(150 + P.density*90)));
const Rbase = 0.30*u*P.scale;
const lw = Math.max(2.5, (0.008 + 0.010*P.energy)*u*P.scale);
const bass = Math.min(0.5, A.bass*0.6);

// palettes
let G=[214,60,20], INK=[196,80,86], PEN=[46,90,96], GRID=true, PAPER=false;
if (sty==='plate'){ G=[36,12,58]; INK=[32,30,20]; PEN=[8,60,44]; PAPER=true; }
else if (sty==='chalk'){ G=[212,26,16]; INK=[200,10,92]; PEN=[50,55,96]; }
else if (sty==='phosphor'){ G=[150,40,7]; INK=[128,80,78]; PEN=[80,60,96]; GRID=false; }
else if (sty==='thermal'){ G=[250,50,8]; INK=[20,85,80]; PEN=[55,90,96]; GRID=false; }
background(G[0],G[1],G[2]);

// technical grid backing (raises coverage + reads as a plate)
if (GRID){
  stroke(G[0], G[1]*0.7, PAPER? G[2]-16 : G[2]+10, 26); strokeWeight(1);
  const gs = u*0.075;
  for (let gx=gs*0.5; gx<width; gx+=gs) line(gx,0,gx,height);
  for (let gy=gs*0.5; gy<height; gy+=gs) line(0,gy,width,gy);
}

// seed-random Fourier coefficients (rebuild on seed)
if (S.seedUsed !== P.seed || !S.co){
  S.seedUsed = P.seed; S.co=[];
  for (let h=2;h<=5;h++){ S.co.push({ax:(hsh(h*3.1)*2-1)*0.5/h, ay:(hsh(h*5.7+2)*2-1)*0.5/h, px:hsh(h*7.3)*6.28, py:hsh(h*9.1+1)*6.28, wx:0.11+hsh(h*2.2)*0.14, wy:0.09+hsh(h*4.4)*0.13}); }
}
const pts=[];
for (let i=0;i<=N;i++){
  const th=i/N*Math.PI*2;
  let x=Math.cos(th), y=Math.sin(th);
  for (let h=0;h<H-1;h++){ const c=S.co[h]; x+=c.ax*Math.cos((h+2)*th + c.px + t*c.wx); y+=c.ay*Math.sin((h+2)*th + c.py + t*c.wy); }
  pts.push({x:cx+x*Rbase, y:cy+y*Rbase});
}
// depth for over/under decision (smooth, slowly drifting)
const depth = i => Math.sin(i/N*Math.PI*2*3 + t*0.3) + 0.5*Math.sin(i/N*Math.PI*2*2 - t*0.21);

// draw the full strand (over-colour, continuous)
noFill(); strokeCap(ROUND); strokeJoin(ROUND);
stroke(INK[0],INK[1],INK[2], P.alpha); strokeWeight(lw);
beginShape(); for (const p of pts) vertex(p.x,p.y); endShape();

// find self-crossings, punch gaps on the UNDER strand, annotate
function xsect(ax,ay,bx,by,cxx,cyy,dx,dy){
  const r1=bx-ax, r2=by-ay, s1=dx-cxx, s2=dy-cyy, den=r1*s2-r2*s1;
  if (Math.abs(den)<1e-9) return null;
  const tt=((cxx-ax)*s2-(cyy-ay)*s1)/den, uu=((cxx-ax)*r2-(cyy-ay)*r1)/den;
  if (tt>0.02&&tt<0.98&&uu>0.02&&uu<0.98) return {x:ax+r1*tt, y:ay+r2*tt, i:0, j:0};
  return null;
}
const cross=[];
for (let i=0;i<N && cross.length<24;i++){
  for (let j=i+2;j<N;j++){
    if (i===0 && j===N-1) continue;
    const X=xsect(pts[i].x,pts[i].y,pts[i+1].x,pts[i+1].y, pts[j].x,pts[j].y,pts[j+1].x,pts[j+1].y);
    if (X){ X.i=i; X.j=j; cross.push(X); if(cross.length>=24) break; }
  }
}
// gap punch (ground colour) on under strand
for (const X of cross){
  const under = depth(X.i) < depth(X.j) ? X.i : X.j;
  const dx=pts[under+1].x-pts[under].x, dy=pts[under+1].y-pts[under].y, dl=Math.hypot(dx,dy)||1;
  const ux=dx/dl, uy=dy/dl, gap=lw*1.9;
  stroke(G[0],G[1],G[2],100); strokeWeight(lw*2.1); strokeCap(PROJECT);
  line(X.x-ux*gap, X.y-uy*gap, X.x+ux*gap, X.y+uy*gap);
}
strokeCap(ROUND);
// travelling "pen" glint (proves it is being drawn) + symmetry break
const pk = ((t*(6+P.speed*10))|0) % N;
for (let d=0; d<8; d++){ const p=pts[(pk+d)%N]; stroke(PEN[0],PEN[1],PEN[2], (90-d*10)*(P.alpha/100)); strokeWeight(lw*0.9); point(p.x,p.y); }
noStroke(); fill(PEN[0],PEN[1],PEN[2],90); ellipse(pts[pk].x,pts[pk].y, lw*2.2, lw*2.2);

// Gauss-code annotation
if (sty!=='thermal'){
  textAlign(CENTER,CENTER); textSize(Math.max(9, u*0.014)); fill(INK[0],INK[1]*0.7, PAPER?30:96, 70*(P.alpha/100)); noStroke();
  for (let c=0;c<Math.min(cross.length,16);c++){ const X=cross[c]; text((c+1), X.x+lw*2.2, X.y-lw*2.2); }
  // title block
  textAlign(LEFT,TOP); textSize(Math.max(9,u*0.015));
  fill(INK[0],INK[1]*0.6, PAPER?26:92, 80*(P.alpha/100));
  text('KNOT DIAGRAM  •  crossings '+cross.length, u*0.03, u*0.03);
}
drawingContext.shadowBlur=0;
blendMode(BLEND);
